llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "In young healthy subjects, the active diacid perindoprilat had 19 ± 7% bioavailability after oral perindopril, below the 20% threshold; this is the most relevant active-diacid ACE inhibitor evidence and supports low oral bioavailability for the query, which is also an active diacid without prodrug masking.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "SQ 29852, a phosphoryl-containing ACE inhibitor, showed 66% oral bioavailability in humans; this supports high but transfers poorly because it contains a basic amine and a phosphonate ester, whereas the query is a phosphinic/carboxylic diacid with no basic center.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Omapatrilat, an active non-prodrug ACE/NEP inhibitor, had about 31% absolute oral bioavailability; this supports high but is structurally distinct from the query's phosphinic diacid and lacks the same ionization profile.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Benazeprilat, an active diacid metabolite, reached 27.1–28.5% bioavailability after oral benazepril; this supports high but reflects administration of the ester prodrug, not direct oral dosing of the diacid itself.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fosinoprilat, the active diacid of fosinopril, bearing free carboxylic and phosphinic acids and no basic amine. The closest active-diacid ACE inhibitor evidence (perindoprilat after oral prodrug) is at or below the 20% threshold, while the high-bioavailability analogues are mostly ester prodrugs or contain a basic amine that the query lacks. Therefore low oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for fosinoprilat itself.",
    "The only sub-20% evidence is for perindoprilat after prodrug administration, not direct dosing of the diacid.",
    "High-bioavailability analogues are predominantly ester prodrugs or contain a basic amine absent in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

